    private void btnCreateInvoiceActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCreateInvoiceActionPerformed
        // TODO add your handling code here:
    // 1. Get data from fields
    String studentIdStr = txtStudentId.getText().trim();
    String term = txtTerm.getText().trim();

    // 2. Validation
    if (studentIdStr.isEmpty() || term.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Please enter both Student ID and Term.", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
        return;
    }

    try {
        Long studentId = Long.parseLong(studentIdStr);

        // 3. Find the student in the database
        dao.StudentDao studentDao = new dao.StudentDao();
        model.student s = studentDao.findById(studentId);

        if (s == null) {
            javax.swing.JOptionPane.showMessageDialog(this, "Student with ID " + studentId + " not found.", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
            return;
        }

        // 4. Find the Fee Structure for this student's class and term
        dao.FeeStructureDao feeDao = new dao.FeeStructureDao();
        model.feeStructure fee = feeDao.findByClassAndTerm(s.getClassLevel(), term);

        if (fee == null) {
            javax.swing.JOptionPane.showMessageDialog(this, "No fee structure found for " + s.getClassLevel() + " for " + term + ". Please set it up first.", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
            return;
        }

        // 5. Create the Invoice
        model.invoice newInvoice = new model.invoice();
        newInvoice.setStudentId(studentId);
        newInvoice.setTerm(term);
        newInvoice.setAmountDue(fee.getTotalAmount());
        newInvoice.setAmountPaid(0.0);
        newInvoice.setStatus("UNPAID");
        newInvoice.setDueDate(new java.util.Date()); // Sets due date to today

        // 6. Save to database
        dao.InvoiceDao invoiceDao = new dao.InvoiceDao();
        invoiceDao.save(newInvoice);

        // 7. Success Message
        javax.swing.JOptionPane.showMessageDialog(this, "Invoice Generated Successfully!\nAmount Due: " + fee.getTotalAmount());
        
        // Clear fields
        txtStudentId.setText("");
        txtTerm.setText("");

    } catch (NumberFormatException e) {
        javax.swing.JOptionPane.showMessageDialog(this, "Student ID must be a number.", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    }    
    }//GEN-LAST:event_btnCreateInvoiceActionPerformed

